[1879071839] = {["ID"] = 1879071839; ["i"] = 6; ["j"] = 2; ["k"] = 24; ["TYPE"] = 105; ["VXP"] = 2000; ["LP"] = 5; ["REP"] = 700; ["FACTION"] = 1879091345; ["TIER"] = 1; ["NAME"] = "Maestro cervecero de la Comarca"; ["LORE"] = "¡Los preparativos para la fiesta cervecera de las Cuatro Cuadernas están completos!"; ["SUMMARY"] = "Assist the 5 Innkeepers"; ["TITLE"] = "Maestro cervecero / Maestra cervecera de la Comarca"; };
[1879073460] = {["ID"] = 1879073460; ["i"] = 5; ["j"] = 2; ["k"] = 34; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 81; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 13; ["NAME"] = "Enemigo / Enemiga de los lobos"; ["LORE"] = "Los lobos han sido durante mucho tiempo una plaga para la pacífica gente de la Comarca. En inviernos duros, pueden descender desde el Norte para atacar al ganado y amenazar a los propios hobbits en feroces manadas. Más recientemente, parece que un mayor número se ha desplazado hacia el sur, y circulan rumores de que están siendo empujados en esa dirección por trasgos o por fuerzas aún más siniestras."; ["SUMMARY"] = "Defeat 50 Wolves in any area"; };
[1879073461] = {["ID"] = 1879073461; ["i"] = 5; ["j"] = 2; ["k"] = 33; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 81; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 19; ["NAME"] = "Enemigo / Enemiga de los lobos II"; ["LORE"] = "Aunque los lobos suelen ser hostiles, la mayoría de la gente los considera peligrosos depredadores y no una amenaza real. Sin embargo, hoy en día uno no puede evitar preguntarse... están bajando del norte en grandes manadas, y parecen más que hambrientos: hay rumores de que muchas de estas manadas fueron criadas por los trasgos de las tierras del norte para ser particularmente feroces y peligrosas contra los Hombres y los hobbits, y para arruinar los rebaños de los que dependen muchas poblaciones de Eriador para su alimento."; ["SUMMARY"] = "Defeat 100 Wolves in any area"; };
[1879073462] = {["ID"] = 1879073462; ["i"] = 5; ["j"] = 2; ["k"] = 32; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 81; ["LP"] = 15; ["MIN_LVL"] = 25; ["NAME"] = "Enemigo / Enemiga de los lobos III"; ["LORE"] = "Cuentan que, en la época del viejo Toro Bramador, la llegada de los trasgos de Golfimbul estuvo precedida por una invasión de lobos muy parecida a la que la gente está viendo hoy en día. Eso no puede ser una buena señal."; ["SUMMARY"] = "Defeat 150 Wolves in any area"; };
[1879073463] = {["ID"] = 1879073463; ["i"] = 5; ["j"] = 2; ["k"] = 37; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 81; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 13; ["NAME"] = "Enemigo / Enemiga de las arañas"; ["LORE"] = "Aunque ningún hobbit que se respete ha tratado mucho con arañas, parece que últimamente han llegado nuevas variantes de esas horribles criaturas —mucho más grandes de lo que debería ser una araña— que migran desde algún lugar al otro lado de las montañas al este. Por motivos desconocidos, estas desagradables criaturas parecen haber desarrollado una gran animosidad hacia los hobbits, convirtiéndolas en un grave peligro para gente Pequeña que viven en los bordes de la Comarca o más allá."; ["SUMMARY"] = "Defeat 50 Spiders in any area"; };
[1879073464] = {["ID"] = 1879073464; ["i"] = 5; ["j"] = 2; ["k"] = 36; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 81; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 29; ["NAME"] = "Enemigo / Enemiga de las arañas II"; ["LORE"] = "¿De dónde han salido estos horrores? ¿Qué pasó con las simpáticas arañitas de jardín que se comían las moscas? Hoy en día tu idea de una araña empieza en unos sesenta centímetros de ancho y sube desde ahí —difícilmente algo que esperarías encontrar en la acogedora Comarca—, y sin embargo ahora parecen comunes en todos los bosques de Eriador. Bastaría para hacer que incluso el hobbit más apacible y sosegado se percate de que las cosas se están poniendo bastante raras."; ["SUMMARY"] = "Defeat 100 Spiders in any area"; };
[1879073465] = {["ID"] = 1879073465; ["i"] = 5; ["j"] = 2; ["k"] = 35; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 81; ["LP"] = 15; ["MIN_LVL"] = 35; ["NAME"] = "Enemigo / Enemiga de las arañas III"; ["LORE"] = "Desde tu juventud recuerdas una vieja leyenda élfica sobre una gran araña que intentó devorar toda la luz del mundo... y cómo, aunque fue expulsada y desapareció para siempre, su prole quedó para multiplicarse y pulular en lugares oscuros y espantosos. Recuerdas cómo ese cuento siempre te recorría un escalofrío cuando tu padre lo contaba —pero con todo lo que has visto últimamente, te preguntas si quizá hubiera algo de verdad en él..."; ["SUMMARY"] = "Defeat 250 Spiders in any area"; };
[1879073466] = {["ID"] = 1879073466; ["i"] = 5; ["j"] = 2; ["k"] = 39; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 81; ["LP"] = 5; ["TIER"] = 1; ["MIN_LVL"] = 29; ["NAME"] = "Enemigo / Enemiga de los Trasgos"; ["LORE"] = "De todas las criaturas al servicio del Enemigo, los trasgos son los únicos que han atacado abiertamente la Comarca. Fueron derrotados por el Toro Bramador Tuk hace muchos años, pero ahora los descendientes de Golfimbul han sido vistos de nuevo cerca de los límites de vuestra hermosa tierra, así como en muchos otros lugares del Norte. Los hobbits han sido llamados a tomar las armas de nuevo, y los Fronteros han redoblado su entrenamiento para no ser tomados desprevenidos por estas salvajes criaturas."; ["SUMMARY"] = "Defeat 100 Goblins in any area"; };
[1879073467] = {["ID"] = 1879073467; ["i"] = 5; ["j"] = 2; ["k"] = 38; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 81; ["LP"] = 10; ["MIN_LVL"] = 35; ["NAME"] = "Enemigo / Enemiga de los Trasgos II"; ["LORE"] = "Parece que la Comarca necesitará pronto un nuevo 'Toro Bramador', porque no hay duda de que los trasgos vuelven a hacer fuerza en el país. Los límites de la Comarca ya no son seguros, y pensar en vuestra gente pacífica enfrentándose a una oleada de esas horribles criaturas desprevenidos te estremece. Habrá que tomar medidas pronto para evitarlo."; ["SUMMARY"] = "Defeat 150 Goblins in any area"; };
[1879073506] = {["ID"] = 1879073506; ["i"] = 5; ["j"] = 2; ["k"] = 42; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 23; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 13; ["NAME"] = "Enemigo / Enemiga de los Muertos"; ["LORE"] = "Desde el principio de los tiempos, espíritus malévolos, entre los que no están exentos los Balrogs de Morgoth, vagaron por el reino de las sombras al servicio del Enemigo. Mediante inmundas brujerías, estos espíritus pueden agitar los huesos putrefactos de los Hombres caídos, convirtiéndolos en terribles tumularios. Para la raza de los Hombres, cuyas almas pasan más allá del mundo cuando mueren, estos monstruos son verdaderas abominaciones."; ["SUMMARY"] = "Defeat 50 Dead in any area"; };
[1879073507] = {["ID"] = 1879073507; ["i"] = 5; ["j"] = 2; ["k"] = 41; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 23; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 19; ["NAME"] = "Enemigo / Enemiga de los Muertos II"; ["LORE"] = "Se dice que cuando el Rey Brujo llegó a Angmar, ejerció dominio sobre muchos espíritus malévolos de Morgoth y los envió desde Angmar y Rhudaur a habitar las Quebradas de los Túmulos, fuera de Bree... el último bastión de los Montaraces de Cardolan. En la Tercera Edad, solo los tumularios permanecen para contar aquellos días malvados."; ["SUMMARY"] = "Defeat 100 Dead in any area"; };
[1879073508] = {["ID"] = 1879073508; ["i"] = 5; ["j"] = 2; ["k"] = 40; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 23; ["LP"] = 15; ["MIN_LVL"] = 25; ["NAME"] = "Enemigo / Enemiga de los Muertos III"; ["LORE"] = "Morgoth, Sauron, el Rey Brujo de Angmar, los terribles Señores Esqueléticos... todos poseen el poder hechicero para infundir en los restos de los muertos espíritus malignos al servicio del Enemigo. Se rumorea que hay valles encantados en el reino de Angmar casi enteramente habitados por estos espíritus y por los espectros viles que generan..."; ["SUMMARY"] = "Defeat 150 Dead in any area"; };
[1879073509] = {["ID"] = 1879073509; ["i"] = 5; ["j"] = 2; ["k"] = 45; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 23; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 13; ["NAME"] = "Enemigo / Enemiga de los Huargos"; ["LORE"] = "Los huargos a menudo son considerados un azote para los Hombres porque su presa preferida son los rebaños y el ganado de los que dependen muchas aldeas en la Tierra Media. En ese aspecto son mucho más devastadores que las razas menores de lobos: se sabe que los huargos masacran el ganado sin pudor incluso después de saciarse, dejando pastizales enteros a la putrefacción."; ["SUMMARY"] = "Defeat 50 Wargs in any area"; };
[1879073510] = {["ID"] = 1879073510; ["i"] = 5; ["j"] = 2; ["k"] = 44; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 23; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 29; ["NAME"] = "Enemigo / Enemiga de los Huargos II"; ["LORE"] = "Los trasgos a veces usan huargos como monturas para extender el alcance de sus ataques contra aldeas y asentamientos, ya que a los trasgos les desagrada atacar más lejos de lo que pueden marchar en una sola noche y aun así volver a la oscura seguridad de sus cuevas antes de la mañana."; ["SUMMARY"] = "Defeat 150 Wargs in any area"; };
[1879073511] = {["ID"] = 1879073511; ["i"] = 5; ["j"] = 2; ["k"] = 43; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 23; ["LP"] = 15; ["MIN_LVL"] = 35; ["NAME"] = "Enemigo / Enemiga de los Huargos III"; ["LORE"] = "No está claro cuál es la verdadera relación entre los trasgos y los huargos. Algunos dicen que están aliados contra enemigos comunes, mientras que otros creen que los trasgos crían y crían activamente a estas criaturas para la guerra. Parece probable que ambas historias sean en parte verdaderas: quizá hace mucho los trasgos criaron huargos, que con el tiempo escaparon y formaron sus propias manadas bajo los líderes más poderosos e inteligentes de su especie... y ahora esas manadas siguen colaborando con los trasgos por conveniencia."; ["SUMMARY"] = "Defeat 250 Wargs in any area"; };
[1879073512] = {["ID"] = 1879073512; ["i"] = 5; ["j"] = 2; ["k"] = 47; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 23; ["LP"] = 5; ["TIER"] = 1; ["MIN_LVL"] = 29; ["NAME"] = "Enemigo / Enemiga de los Montañeses"; ["LORE"] = "Durante muchos años han existido tribus de Hombres que han evitado la autoridad de los reyes y la vida en grandes ciudades y poblaciones. Si bien algunos de ellos podrían ser considerados aliados por los Hombres de Gondor o de Rohan, con demasiada frecuencia caen bajo la influencia del Enemigo, que aprovecha su desconfianza hacia los grandes Reinos, los amenaza con fuerzas ocultas o los seduce con riquezas y poder falsos. Así ha ocurrido que los Reinos de la Tierra Media a menudo se han visto en guerra con la gente de las Colinas cuando el Enemigo se alza, y esta era no parece ser la excepción."; ["SUMMARY"] = "Defeat 150 Hillmen in any area"; };
[1879073513] = {["ID"] = 1879073513; ["i"] = 5; ["j"] = 2; ["k"] = 46; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 23; ["LP"] = 10; ["MIN_LVL"] = 35; ["NAME"] = "Enemigo / Enemiga de los Montañeses II"; ["LORE"] = "Parece que viejas supersticiones y el miedo al oscuro poder del Enemigo son lo que empuja a estos Montañeses a reunirse bajo sus banderas: antiguas semillas sembradas hace mucho tiempo en el corazón de los Hombres por el Señor Oscuro, para disponer de servidores cuando se prepare a resurgir. Durante largo tiempo ha sido tanto la fuerza como la perdición de los Hombres que sus corazones les pertenezcan y que puedan escoger el camino que deseen...."; ["SUMMARY"] = "Defeat 250 Hillmen in any area"; };
[1879073549] = {["ID"] = 1879073549; ["i"] = 5; ["j"] = 2; ["k"] = 20; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 65; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 13; ["NAME"] = "Enemigo / Enemiga de los Trasgos"; ["LORE"] = "Los trasgos fueron creados por Morgoth hace mucho tiempo, cuando Elfos cautivos fueron torturados y retorcidos hasta convertirse en parodias de sí mismos, y lanzados al mundo como enemigos eternos de sus antiguos congéneres. Todo lo bueno que había en ellos fue transformado en mal, y los Elfos han luchado durante edades para erradicarlos de la Tierra Media... sin éxito."; ["SUMMARY"] = "Defeat 50 Goblins in any area"; };
[1879073550] = {["ID"] = 1879073550; ["i"] = 5; ["j"] = 2; ["k"] = 19; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 65; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 19; ["NAME"] = "Enemigo / Enemiga de los Trasgos II"; ["LORE"] = "Los trasgos son una burla de la vida, retorcidos por el Enemigo para servir sin cuestionar como un suministro infinito de soldados rasos en sus guerras. Por suerte, la cría de lealtad ciega los ha dejado sin imaginación y con pocas habilidades, por lo que no son rival para guerreros élficos entrenados. Aun así, sus números son vastos, y si solo un elfo cae por cada cien de los suyos, es una gran pérdida."; ["SUMMARY"] = "Defeat 100 Goblins in any area"; };
[1879073551] = {["ID"] = 1879073551; ["i"] = 5; ["j"] = 2; ["k"] = 18; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 65; ["LP"] = 15; ["MIN_LVL"] = 25; ["NAME"] = "Enemigo / Enemiga de los Trasgos III"; ["LORE"] = "No está claro qué piensan los trasgos de los Elfos, ya que rara vez están dispuestos a hablar del asunto, salvo desde el extremo opuesto de un arma afilada. ¿Son siquiera conscientes de su lejana ascendencia, de cuando vivían entre los Pueblos Libres? ¿Odian a los Elfos porque su Señor Oscuro se lo ordena, o porque recuerdan algo de hace mucho y tratan de destruirlos por una envidiosa rabia hacia su lugar en la luz?"; ["SUMMARY"] = "Defeat 150 Goblins in any area"; };
[1879073552] = {["ID"] = 1879073552; ["i"] = 5; ["j"] = 2; ["k"] = 23; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 65; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 13; ["NAME"] = "Enemigo / Enemiga de los Orcos"; ["LORE"] = "Criados por el Enemigo para la guerra terrestre, los Orcos son más grandes y resistentes que sus primos trasgos, aunque sus orígenes son los mismos. Militares y brutales, conservan cierta habilidad natural para trabajar la madera y el metal, pero la aplican únicamente a la construcción de armas y otras máquinas de guerra."; ["SUMMARY"] = "Defeat 50 Orcs in any area"; };
[1879073553] = {["ID"] = 1879073553; ["i"] = 5; ["j"] = 2; ["k"] = 22; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 65; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 29; ["NAME"] = "Enemigo / Enemiga de los Orcos II"; ["LORE"] = "A diferencia de los trasgos, los Orcos han sido criados con una mentalidad marcial y forman la columna vertebral de los ejércitos del Enemigo. No son ni cobardes ni débiles —aunque no pueden aspirar a igualar la destreza marcial de los Elfos—, pero su número y su industria bélica son vastos cuando son movilizados por sus señores sombríos."; ["SUMMARY"] = "Defeat 100 Orcs in any area"; };
[1879073554] = {["ID"] = 1879073554; ["i"] = 5; ["j"] = 2; ["k"] = 21; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 65; ["LP"] = 15; ["MIN_LVL"] = 35; ["NAME"] = "Enemigo / Enemiga de los Orcos III"; ["LORE"] = "Aunque los Orcos detestan el sol casi tanto como sus hermanos menores, los trasgos, lo toleran mejor y pueden ser forzados a soportarlo por un tiempo cuando la necesidad —o el látigo de sus amos— lo exige. Aun así, ha sido durante largo tiempo una artimaña del Enemigo conjurar vastas nubes de humo o tinieblas para proteger a sus tropas de los rayos del sol y para ocultar sus movimientos frente a espías y exploradores."; ["SUMMARY"] = "Defeat 250 Orcs in any area"; };
[1879073555] = {["ID"] = 1879073555; ["i"] = 5; ["j"] = 2; ["k"] = 25; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 65; ["LP"] = 5; ["TIER"] = 1; ["MIN_LVL"] = 29; ["NAME"] = "Enemigo / Enemiga de los dragonzuelos"; ["LORE"] = "Los dragones fueron creados hace muchas eras para quebrar el poder de los Elfos en el Norte —y en ello tuvieron éxito gracias a su inmenso poder y astucia, actuando como una punta de lanza mortal de las huestes del Enemigo ante la que nadie podía resistir. Al igual que los Elfos, los Dragones nunca fueron numerosos, y su carácter salvaje hace que pocas crías lleguen a la adultez. Sus números también han menguado en la Tierra Media —pero recientemente muchos de los dragonzuelos menores han sido liberados desde Angmar, lo cual es motivo de gran preocupación; si estas bestias menores han reaparecido, ¿estarán los Dragones lejos? Sea como sea, estas criaturas deben ser destruidas."; ["SUMMARY"] = "Defeat 100 Drakes in any area"; };
[1879073556] = {["ID"] = 1879073556; ["i"] = 5; ["j"] = 2; ["k"] = 24; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 65; ["LP"] = 10; ["MIN_LVL"] = 35; ["NAME"] = "Enemigo / Enemiga de los dragonzuelos II"; ["LORE"] = "Aunque sólo posean una fracción del poder de sus parientes mayores, un dragonzuelo es, sin duda, un enemigo mortal. Incluso entre los Primeros Nacidos es un honor enfrentarse a una criatura así y salir victorioso. Nadie sabe de dónde surgieron los dragonzuelos: ¿qué criatura encontró el Enemigo para retorcerla hasta convertirla en una forma y un poder tan temibles como los de la estirpe de los dragones? Sus orígenes están ocultos, incluso para los Elfos."; ["SUMMARY"] = "Defeat 150 Drakes in any area"; };
[1879073586] = {["ID"] = 1879073586; ["i"] = 5; ["j"] = 2; ["k"] = 12; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 73; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 13; ["NAME"] = "Enemigo / Enemiga de los Duramano"; ["LORE"] = "Los enanos Duramano parecen haber dado la espalda a los Pueblos Libres de la Tierra Media y se han rebelado contra el legítimo gobierno del Pueblo de Durin."; ["SUMMARY"] = "Defeat 50 Dourhand in any area"; };
[1879073587] = {["ID"] = 1879073587; ["i"] = 5; ["j"] = 2; ["k"] = 11; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 73; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 19; ["NAME"] = "Enemigo / Enemiga de los Duramano II"; ["LORE"] = "Celosos de la riqueza y el estatus de los barbiluengos —especialmente desde que el Pueblo de Durin recuperó la Montaña Solitaria— los Duramano han conspirado durante años para usurpar su posición como líderes de los enanos de las Montañas Azules."; ["SUMMARY"] = "Defeat 100 Dourhand in any area"; };
[1879073588] = {["ID"] = 1879073588; ["i"] = 5; ["j"] = 2; ["k"] = 10; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 73; ["LP"] = 15; ["MIN_LVL"] = 25; ["NAME"] = "Enemigo / Enemiga de los Duramano III"; ["LORE"] = "Desde los registros más antiguos, la historia ha estado llena de historias de traición y tragedia. La rebelión de los Duramano es sólo el último capítulo de esta larga y dolorosa letanía. Es hora de poner fin a ese capítulo..."; ["SUMMARY"] = "Defeat 150 Dourhand in any area"; };
[1879073589] = {["ID"] = 1879073589; ["i"] = 5; ["j"] = 2; ["k"] = 15; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 73; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 13; ["NAME"] = "Enemigo / Enemiga de los Trasgos"; ["LORE"] = "Trasgos y enanos se han despreciado desde que se vieron por primera vez. Son enemigos naturales tanto en la superficie como bajo tierra, y las innumerables hordas de los trasgos se estrellan año tras año contra las infatigables defensas de los enanos, desgastándolas como las mareas contra la roca."; ["SUMMARY"] = "Defeat 50 Goblins in any area"; };
[1879073590] = {["ID"] = 1879073590; ["i"] = 5; ["j"] = 2; ["k"] = 14; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 73; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 29; ["NAME"] = "Enemigo / Enemiga de los Trasgos II"; ["LORE"] = "Los enanos siempre han tenido la ventaja sobre los trasgos en cuanto a destreza en el combate y en la calidad de armas, armaduras y fortificaciones. Sin embargo, los trasgos siempre han tenido la ventaja en número, y es una ventaja considerable."; ["SUMMARY"] = "Defeat 100 Goblins in any area"; };
[1879073591] = {["ID"] = 1879073591; ["i"] = 5; ["j"] = 2; ["k"] = 13; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 73; ["LP"] = 15; ["MIN_LVL"] = 35; ["NAME"] = "Enemigo / Enemiga de los Trasgos III"; ["LORE"] = "Los trasgos son un curioso caso de mentalidad de grupo. Individualmente son cobardes que se estremecen ante cualquiera que les parezca más fuerte; en grandes masas se lanzan con una salvaje inconsciencia contra picas y hachas. La sabiduría popular dice que, en grandes grupos, los trasgos de la primera línea no tienen opción, ya que son empujados por las masas que los siguen, y por eso luchan como animales acorralados. Por lo que has visto, puede haber algo de verdad en ello."; ["SUMMARY"] = "Defeat 250 Goblins in any area"; };
[1879073592] = {["ID"] = 1879073592; ["i"] = 5; ["j"] = 2; ["k"] = 17; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 73; ["LP"] = 5; ["TIER"] = 1; ["MIN_LVL"] = 29; ["NAME"] = "Enemigo / Enemiga de los trolls"; ["LORE"] = "Los trolls son una amenaza particularmente letal para los enanos. Capaces de destruir las fortificaciones más sólidas y de prosperar en dominios subterráneos donde el sol no los amenaza, a menudo se han utilizado para encabezar grandes asaltos contra los reinos enanos."; ["SUMMARY"] = "Defeat 100 Trolls in any area"; };
[1879073593] = {["ID"] = 1879073593; ["i"] = 5; ["j"] = 2; ["k"] = 16; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 73; ["LP"] = 10; ["MIN_LVL"] = 35; ["NAME"] = "Enemigo / Enemiga de los trolls II"; ["LORE"] = "Todo lo contrario a los trasgos: la mayoría de los trolls poseen poca astucia o inteligencia. Son, eso sí, casi temerariamente valientes y aplastan sin contemplaciones todo a su paso. Solo si están gravemente heridos es probable que se rebelen; aunque la visión de un troll de las cuevas descontrolado entre sus manipuladores trasgos suele provocar una sonrisa incluso en los veteranos más curtidos."; ["SUMMARY"] = "Defeat 150 Trolls in any area"; };
[1879084435] = {["ID"] = 1879084435; ["i"] = 6; ["j"] = 10; ["k"] = 3; ["TYPE"] = 103; ["VXP"] = 4000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091341; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Bastiones de esperanza"; ["LORE"] = "Incluso en los desiertos arrasados de Angmar, quedan algunos pequeños bastiones de resistencia y valor para luchar contra la oscuridad. Estos puestos avanzados y campamentos se encuentran ocultos y bien defendidos en las colinas de esta tierra oscura, brindando ayuda a aquellos que se alzan en armas contra los poderes de Carn Dûm."; ["SUMMARY"] = "Find 5 outposts of the Free People"; };
[1879085025] = {["ID"] = 1879085025; ["i"] = 6; ["j"] = 10; ["k"] = 4; ["TYPE"] = 103; ["VXP"] = 2000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091341; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "El círculo de la desesperación"; ["LORE"] = "Se rumorea que la antigua fortaleza del Rey Brujo de Angmar está rodeada por ocho torres temibles dentro de las cuales residían sus lugartenientes durante la larga guerra con Arnor, tejiendo su temible magia allí contra las fuerzas del Oeste."; ["SUMMARY"] = "Find 8 towers of Despair"; };
[1879085026] = {["ID"] = 1879085026; ["i"] = 6; ["j"] = 10; ["k"] = 5; ["TYPE"] = 103; ["VXP"] = 4000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091341; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "El camino de la guerra"; ["LORE"] = "Hay un gran camino que atraviesa las Tierras baldías de Angmar hasta las mismas puertas de Carn Dûm. Es a lo largo de este camino que las oscuras huestes marchan para someter a los Pueblos Libres de Eriador al yugo del Enemigo."; ["SUMMARY"] = "Find 5 locations on the path to Carn Dum"; };
[1879086558] = {["ID"] = 1879086558; ["i"] = 5; ["j"] = 3; ["k"] = 3; ["TYPE"] = 104; ["LP"] = 20; ["TIER"] = 1; ["NAME"] = "Las Sombras de Angmar"; ["LORE"] = "Desentraña el relato épico de las Sombras de Angmar."; ["SUMMARY"] = "Complete Epic Vol. I, Book I through Vol. I, Book VIII."; ["TITLE"] = "una Luz en la Sombra"; };
[1879086561] = {["ID"] = 1879086561; ["i"] = 6; ["j"] = 9; ["k"] = 10; ["TYPE"] = 105; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 300; ["FACTION"] = 1879091343; ["TIER"] = 3; ["NAME"] = "Errante de Evendim"; ["LORE"] = "Las tierras de Evendim, una vez la capital de Arnor, el Reino del Norte, hace mucho que no son habitadas por los Hombres, a excepción de pequeños grupos de saqueadores que buscan en las antiguas ruinas y tumbas que se encuentran bordeando el gran lago. Con las fuerzas del Norte convocadas para la guerra, aquellos que ganen el control de la antigua capital podrían ganar una ventaja crítica en el conflicto que se acerca."; ["SUMMARY"] = "Complete 30 quests in Evendim"; };
[1879086562] = {["ID"] = 1879086562; ["i"] = 6; ["j"] = 9; ["k"] = 9; ["TYPE"] = 105; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 2; ["NAME"] = "Peregrino / Peregrina de Evendim"; ["LORE"] = "En eras pasadas, cuando el Reino de Arnor se dividió en facciones rivales bajo la influencia maligna de Angmar, la ciudad de Annúminas en Evendim perdió su influencia y fue finalmente abandonada. La capital pasó a ser Fornost, que con el tiempo se convirtió en la sede de la monarquía de Arthedain."; ["SUMMARY"] = "Complete 60 quests in Evendim"; };
[1879086563] = {["ID"] = 1879086563; ["i"] = 6; ["j"] = 9; ["k"] = 8; ["TYPE"] = 105; ["VXP"] = 2000; ["LP"] = 15; ["REP"] = 700; ["FACTION"] = 1879091343; ["TIER"] = 1; ["NAME"] = "Vigilante de Evendim"; ["LORE"] = "Aunque no hay industria, agricultura, ni ningún bastión de gran importancia estratégica en Evendim, podría convertirse en un gran símbolo entre los Hombres del Norte, si la gran capital de Annúminas volviera a alzarse algún día bajo el estandarte de los antiguos reyes."; ["SUMMARY"] = "Complete 90 quests in Evendim"; };
[1879086861] = {["ID"] = 1879086861; ["i"] = 6; ["j"] = 9; ["k"] = 19; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 3; ["MIN_LVL"] = 20; ["NAME"] = "Defensor / Defensora de tumbas"; ["LORE"] = "Los saqueadores de tumbas llevan rebuscando desde hace mucho en los ruinosos senderos de Annúminas y las tumbas de los reyes caídos de antaño. Los montaraces del Norte se alían con quienes se alce en armas para mantener a estos ladrones y granujas a raya."; ["SUMMARY"] = "Defeat 90 Tomb-robbers in Evendim"; ["TITLE"] = "Guardián de tumbas"; };
[1879086862] = {["ID"] = 1879086862; ["i"] = 6; ["j"] = 9; ["k"] = 18; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 20; ["NAME"] = "Defensor / Defensora de tumbas (avanzado)"; ["LORE"] = "Aquellos que se atreven a profanar las tumbas de los antiguos Dúnedain se vuelven más atrevidos gracias al caos y al miedo de una guerra que se cierne sobre las tierras del Norte. Alzarse en armas contra estos villanos sin principios es una de las más nobles causas."; ["SUMMARY"] = "Defeat 180 Tomb-robbers in Evendim"; };
[1879086863] = {["ID"] = 1879086863; ["i"] = 6; ["j"] = 9; ["k"] = 21; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 3; ["MIN_LVL"] = 20; ["NAME"] = "Azote de Limrafn"; ["LORE"] = "Los Limrafn son una forma menor y débil de un espíritu malvado. Ni los Elfos pueden afirmar qué es lo que los atrae a Evendim en tal cantidad."; ["SUMMARY"] = "Defeat 50 Limrafn in Evendim"; ["TITLE"] = "Guardián de los Misterios"; };
[1879086864] = {["ID"] = 1879086864; ["i"] = 6; ["j"] = 9; ["k"] = 20; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 20; ["NAME"] = "Azote de Limrafn (avanzado)"; ["LORE"] = "Has visto muchas de estas extrañas luces en Evendim últimamente... parecen estar multiplicándose con la presencia de Hombres y otras fuerzas. ¿Es posible que estas extrañas entidades estén siendo despertadas o atraídas por las escaramuzas que se libran en estas tierras, que una vez estuvo casi vacía?"; ["SUMMARY"] = "Defeat 100 Limrafn in Evendim"; };
[1879086865] = {["ID"] = 1879086865; ["i"] = 6; ["j"] = 9; ["k"] = 23; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Gauredain"; ["LORE"] = "Las leyendas han hablado desde hace mucho de hombres lobo que acechan en la noche, pero ahora que has conocido a los Gauredain sospechas que conoces más la verdad detrás de estas historias. Si son Hombres, apenas lo son ya. Son más grandes que la mayoría de los Hombres en estatura, aun encorvados hacia delante y usando solo herramientas y lenguaje primitivo, y a menudo vestidos con pieles de lobo."; ["SUMMARY"] = "Defeat 90 Gauradain in Evendim"; ["TITLE"] = "Azote de los Gauredain"; };
[1879086866] = {["ID"] = 1879086866; ["i"] = 6; ["j"] = 9; ["k"] = 22; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Gauredain (avanzado)"; ["LORE"] = "Si los Guaredain eran conocidos para los antiguos reyes de Arnor, pocas historias han sobrevivido hasta hoy que hablen de ellos. Más parece que estos Hombres salvajes llegaran a Evendim desde Forochel, en el lejano norte."; ["SUMMARY"] = "Defeat 180 Gauradain in Evendim"; };
[1879086867] = {["ID"] = 1879086867; ["i"] = 6; ["j"] = 9; ["k"] = 25; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Azote de gigantes"; ["LORE"] = "Una tribu de gigantes de piedra parece haberse instalado en las colinas del oeste de Evendim. Aunque no son tan grandes en estatura como sus legendarios primos de las Montañas Nubladas, son poderosos oponentes cuando montan cólera y son un rival más que digno para cualquier soldado solitario."; ["SUMMARY"] = "Defeat 40 Giants in Evendim"; ["TITLE"] = "Enemigo de los Gigantes"; };
[1879086868] = {["ID"] = 1879086868; ["i"] = 6; ["j"] = 9; ["k"] = 24; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 20; ["NAME"] = "Azote de gigantes (avanzado)"; ["LORE"] = "Nadie parece saber con quienes están aliados los gigantes. De hecho, parece que no sirven nadie salvo a sí mismos dada su caprichosa naturaleza. Sin embargo, si estas tierras caen en manos del Enemigo, los gigantes sin duda serán forzados a servirle como terribles soldados."; ["SUMMARY"] = "Defeat 80 Giants in Evendim"; };
[1879086869] = {["ID"] = 1879086869; ["i"] = 6; ["j"] = 9; ["k"] = 27; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 3; ["MIN_LVL"] = 20; ["NAME"] = "Azote de trasgos"; ["LORE"] = "La amenaza de los trasgos parece estar por todas partes estos días, incluso en las fronteras de la misma Comarca. Los rumores dicen que en Evendim hay una nueva raza de estas inmundas criaturas: los extraños boggarts... cobardes y gimoteantes seres que cazan en manada a sus presas."; ["SUMMARY"] = "Defeat 90 Goblins in Evendim"; ["TITLE"] = "Enemigo de los trasgos"; };
[1879086870] = {["ID"] = 1879086870; ["i"] = 6; ["j"] = 9; ["k"] = 26; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 20; ["NAME"] = "Azote de trasgos (avanzado)"; ["LORE"] = "Parece que los trasgos delsur de Evendim todavía no han llegado en gran número. Quizás solo están aquí para hostigar a la gente de la Comarca y distraer a los Montaraces de objetivos más importantes. Sin embargo, los trasgos usan profundos túneles para moverse evitando la vista de incluso los exploradores de vista más aguda, así que pueden aparecer de repente en gran número para sembrar el caos entre los desprevenidos."; ["SUMMARY"] = "Defeat 180 Goblins in Evendim"; };
[1879086871] = {["ID"] = 1879086871; ["i"] = 6; ["j"] = 9; ["k"] = 29; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 3; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Kergrim"; ["LORE"] = "Los Kergrim son otro misterio de las tierras de Evendim. Los montaraces parecen creer que son primos distantes de las bestias de las nieves que habitan en las Montañas Nubladas, pero nadie sabe decir por qué están aquí, o qué poder los ha retorcido para convertirlos en estas formas espantosas. Lo que es seguro es que la mano del Enemigo tiene algo que ver aquí de algún modo, aunque no hay prueba clara de su poder aquí."; ["SUMMARY"] = "Defeat 50 Kergrim in Evendim"; ["TITLE"] = "Pesadilla de los Kergrim"; };
[1879086872] = {["ID"] = 1879086872; ["i"] = 6; ["j"] = 9; ["k"] = 28; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Azote de Kergrim (avanzado)"; ["LORE"] = "Muchos de los inmundos Kergrim parecen haber infestado el valle en el que se encuentran las tumbas de los antiguos reyes Dúnedain. No hay duda de que los Montaraces del Norte están enfurecidos por la posible profanación de las tumbas de sus ancestros por estas bestias, pero no apenas pueden disponer de hombres para erradicarlos."; ["SUMMARY"] = "Defeat 100 Kergrim in Evendim"; };
[1879086873] = {["ID"] = 1879086873; ["i"] = 6; ["j"] = 9; ["k"] = 31; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 3; ["MIN_LVL"] = 20; ["NAME"] = "Azote de salamandras"; ["LORE"] = "Las salamandras de Evendim siempre han sido difíciles de encontrar. Esta extraña ramificación de la famlia de los dragones tiene una gran afinidad con el fuego, que desata sin control contra cualquier enemigo que ose molestarla."; ["SUMMARY"] = "Defeat 90 Salamanders in Evendim"; ["TITLE"] = "Apagador de Llamas"; };
[1879086874] = {["ID"] = 1879086874; ["i"] = 6; ["j"] = 9; ["k"] = 30; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 20; ["NAME"] = "Azote de salamandras (avanzado)"; ["LORE"] = "Extrañamente, las salamandras se encuentran frecuentemente cerca de masas de agua como ríos o lagos, aunque también se las puede encontrar en ciénagas pantanosas o desiertos de arena. Los eruditos creen que esto pueda deberse a la tendencia de estas crituras a quemar toda vegetación cercana, haciendo así que un área deje de ser habitable a menos que masas de agua u otro terreno ignífugo contengan los incendios que frecuentemente desencadenan."; ["SUMMARY"] = "Defeat 180 Salamanders in Evendim"; };
[1879089144] = {["ID"] = 1879089144; ["i"] = 6; ["j"] = 9; ["k"] = 5; ["TYPE"] = 103; ["VXP"] = 2000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Tumbas de Evendim"; ["LORE"] = "Los reyes de Annúminas fueron enterrados en tumbas a lo largo del camino a la puerta de la ciudad. Nueve fueron reyes que gobernaron sobre Arnor desde su trono en esta ciudad, pero no todos fueron enterrados en el Camino de los Reyes..."; ["SUMMARY"] = "Find 8 tombs of the Dunedain kings"; };
[1879089145] = {["ID"] = 1879089145; ["i"] = 6; ["j"] = 9; ["k"] = 4; ["TYPE"] = 103; ["VXP"] = 2000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Ruinas de Evendim"; ["LORE"] = "Explora las ruinas de la antigua Arnor."; ["SUMMARY"] = "Find 8 ruins in Evendim"; };
[1879089146] = {["ID"] = 1879089146; ["i"] = 6; ["j"] = 9; ["k"] = 6; ["TYPE"] = 103; ["VXP"] = 2000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091343; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Tierras salvajes de Evendim"; ["LORE"] = "Una vez la capital del Norte, Evendim siempre ha sido una región salvaje y llena de misterios... que respectivamente se han vuelto más peligrosas y extraños aun tras los largos años que han pasado desde que Annúminas fuera abandonada. Lejos, más allá de las aguas del lago Evendim se hallan tierras inexploradas por los Hombres."; ["SUMMARY"] = "Find 8 locations in the wilds of Evendim"; };
[1879093958] = {["ID"] = 1879093958; ["i"] = 6; ["j"] = 1; ["k"] = 36; ["TYPE"] = 106; ["LP"] = 10; ["REP"] = 900; ["FACTION"] = 1879091340; ["MIN_LVL"] = 15; ["NAME"] = "Ejecutor de los malvados"; ["LORE"] = "Entre los horrores putrefactos de las Quebradas de los Túmulos, una congregación de criaturas malignas y corruptas ejerce su dominio sobre una corte negra. Debes encontrar y dar muerte a cada una de estas malvadas abominaciones para tener alguna esperanza de arrebatar a la oscuridad el control de este lugar antaño sagrado."; ["SUMMARY"] = "Defeat the 6 leaders of the Barrow Downs"; ["TITLE"] = "Verdugo de los Malvados"; };
[1879093959] = {["ID"] = 1879093959; ["i"] = 6; ["j"] = 1; ["k"] = 35; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 700; ["FACTION"] = 1879091340; ["TIER"] = 1; ["MIN_LVL"] = 10; ["NAME"] = "Némesis de los caídos"; ["LORE"] = "Se ha descubierto que los túmulos recientemente abiertos son hogar de espíritus llenos de odio. Aquellos que luchen para derrotar a estos espíritus y los devuelvan al descanso eterno del que escaparon serán reconocidos por la agradecida gente de las Tierras de Bree."; ["SUMMARY"] = "Defeat 50 Barrow-spirits in Haudh Iarchith"; ["TITLE"] = "Némesis de los Caídos"; };
[1879093960] = {["ID"] = 1879093960; ["i"] = 6; ["j"] = 1; ["k"] = 34; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 900; ["FACTION"] = 1879091340; ["MIN_LVL"] = 10; ["NAME"] = "Némesis de los caídos (avanzado)"; ["LORE"] = "Se ha descubierto que los túmulos recientemente abiertos son hogar de espíritus llenos de odio. Aquellos que luchen para derrotar a estos espíritus y los devuelvan al descanso eterno del que escaparon serán reconocidos por la agradecida gente de las Tierras de Bree."; ["SUMMARY"] = "Defeat 100 Barrow-spirits in Haudh Iarchith"; };
[1879093961] = {["ID"] = 1879093961; ["i"] = 6; ["j"] = 1; ["k"] = 31; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 700; ["FACTION"] = 1879091340; ["TIER"] = 1; ["MIN_LVL"] = 10; ["NAME"] = "Cazador / Cazadora de arañas"; ["LORE"] = "La malvada araña Gwigon ha convertido en su guarida el laberíntico túmulo de Taradan y allí su prole se multiplica. Buscan atrapar a cualquier ser vivo lo suficientemente insensato como para aventurarse entre los huesos y el polvo de los príncipes caídos hace mucho tiempo."; ["SUMMARY"] = "Defeat 30 Barrow-spiders in the Barrow of Taradan"; ["TITLE"] = "Cazador de crías"; };
[1879093962] = {["ID"] = 1879093962; ["i"] = 6; ["j"] = 1; ["k"] = 30; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 900; ["FACTION"] = 1879091340; ["MIN_LVL"] = 10; ["NAME"] = "Cazador / Cazadora de arañas (avanzado)"; ["LORE"] = "La malvada araña Gwigon ha convertido en su guarida el laberíntico túmulo de Taradan y allí su prole se multiplica. Buscan atrapar a cualquier ser vivo lo suficientemente insensato como para aventurarse entre los huesos y el polvo de los príncipes caídos hace mucho tiempo."; ["SUMMARY"] = "Defeat 60 Barrow-spiders in the Barrow of Taradan"; };
[1879093963] = {["ID"] = 1879093963; ["i"] = 6; ["j"] = 1; ["k"] = 33; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 700; ["FACTION"] = 1879091340; ["TIER"] = 1; ["MIN_LVL"] = 10; ["NAME"] = "Cavador / Cavadora de tumbas"; ["LORE"] = "El olor a tierra de tumba siempre impregna el aire de las Quebradas de los Túmulos, siendo un recordatorio constante de cuántos yacen enterrados en sus sinuosos pasillos... aunque parece que ahora pocos de ellos descansan como deberían..."; ["SUMMARY"] = "Defeat 50 Barrow Wardens in Haudh Iarchith"; ["TITLE"] = "Sepulturero"; };
