[1879093965] = {["ID"] = 1879093965; ["i"] = 6; ["j"] = 3; ["k"] = 26; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 700; ["FACTION"] = 1879091408; ["TIER"] = 1; ["MIN_LVL"] = 40; ["NAME"] = "Maestro / Maestra de las bestias"; ["LORE"] = "Muchas bestias salvajes acechan las ruinas de Sarnúr, pero estas criaturas han sido esclavizadas o retorcidas a la voluntad de Angmar mediante los ardides de los trasgos, que las crían y las atormentan con crueldad. Muchas actúan ahora como espías y guardianes para los Duramano y deben ser destruidas antes de que sean desatadas sobre las tierras de Ered Luin para causar daño y caos entre sus gentes."; ["SUMMARY"] = "Defeat 80 beasts in Sarnúr"; ["TITLE"] = "Maestro de las Bestias"; };
[1879093966] = {["ID"] = 1879093966; ["i"] = 6; ["j"] = 3; ["k"] = 25; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 900; ["FACTION"] = 1879091408; ["MIN_LVL"] = 40; ["NAME"] = "Maestro / Maestra de las bestias (Avanzado)"; ["LORE"] = "Muchas bestias salvajes acechan las ruinas de Sarnúr, pero estas criaturas han sido esclavizadas o retorcidas a la voluntad de Angmar mediante los ardides de los trasgos, que las crían y las atormentan con crueldad. Muchas actúan ahora como espías y guardianes para los Duramano y deben ser destruidas antes de que sean desatadas sobre las tierras de Ered Luin para causar daño y caos entre sus gentes."; ["SUMMARY"] = "Defeat 160 beasts in Sarnúr"; };
[1879093967] = {["ID"] = 1879093967; ["i"] = 6; ["j"] = 3; ["k"] = 24; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 700; ["FACTION"] = 1879091408; ["TIER"] = 1; ["MIN_LVL"] = 40; ["NAME"] = "Perdición del Traidor"; ["LORE"] = "Las ruinas enanas de Sarnúr han sido descubiertas y ocupadas por los Duramano, quienes planean usarlas como base desde la cual atacar a los Barbiluengos. Peor aún, se han aliado con criaturas malvadas y corrompidas cuya verdadera lealtad está al servicio de los poderes de Angmar. Debes llevar tu lucha contra los Duramano a las calles quebradas de Sarnúr antes de que refuercen su poder y reciban más apoyo de las fuerzas enviadas desde Angmar."; ["SUMMARY"] = "Defeat 80 Dourhand dwarves in Sarnúr"; ["TITLE"] = "La pesadilla del traidor"; };
[1879093968] = {["ID"] = 1879093968; ["i"] = 6; ["j"] = 3; ["k"] = 23; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 900; ["FACTION"] = 1879091408; ["MIN_LVL"] = 40; ["NAME"] = "Perdición del Traidor (Avanzado)"; ["LORE"] = "Las ruinas enanas de Sarnúr han sido descubiertas y ocupadas por los Duramano, quienes planean usarlas como base desde la cual atacar a los Barbiluengos. Peor aún, se han aliado con criaturas malvadas y corrompidas cuya verdadera lealtad está al servicio de los poderes de Angmar. Debes llevar tu lucha contra los Duramano a las calles quebradas de Sarnúr antes de que refuercen su poder y reciban más apoyo de las fuerzas enviadas desde Angmar."; ["SUMMARY"] = "Defeat 160 Dourhand dwarves in Sarnúr"; };
[1879093969] = {["ID"] = 1879093969; ["i"] = 6; ["j"] = 3; ["k"] = 29; ["TYPE"] = 104; ["LP"] = 10; ["REP"] = 900; ["FACTION"] = 1879091408; ["MIN_LVL"] = 42; ["NAME"] = "Vengador de Sarnúr"; ["LORE"] = "Una alianza de enemigos conspira contra Ered Luin desde las antiguas ruinas de Sarnúr, mientras los traicioneros Duramano intentan reunir fuerzas para lanzarlas contra sus odiados primos, los Barbiluengos. Buscan reclamar legitimidad ocupando el asiento de una antigua ciudad enana, pero su presencia junto a tales maldades no hace sino profanar la santidad de sus ancestros."; ["SUMMARY"] = "Defeat the 6 leaders of Sarnúr"; ["TITLE"] = "Vengador de Sarnúr"; };
[1879093970] = {["ID"] = 1879093970; ["i"] = 6; ["j"] = 3; ["k"] = 28; ["TYPE"] = 106; ["LP"] = 5; ["REP"] = 700; ["FACTION"] = 1879091408; ["TIER"] = 1; ["MIN_LVL"] = 40; ["NAME"] = "Noqueador de Trolls"; ["LORE"] = "Parece que los trolls que habitan Sarnúr pertenecen a una cepa particularmente torpe... aunque brutal. Con corazones de hielo endurecido, destruirán todo lo que se interponga en su camino a menos que puedas detenerlos."; ["SUMMARY"] = "Defeat 40 trolls in Sarnúr"; ["TITLE"] = "Pateador de trolls"; };
[1879093971] = {["ID"] = 1879093971; ["i"] = 6; ["j"] = 3; ["k"] = 27; ["TYPE"] = 106; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 900; ["FACTION"] = 1879091408; ["MIN_LVL"] = 40; ["NAME"] = "Noqueador de Trolls (Avanzado)"; ["LORE"] = "Parece que los trolls que habitan Sarnúr pertenecen a una cepa particularmente torpe... aunque brutal. Con corazones de hielo endurecido, destruirán todo lo que se interponga en su camino a menos que puedas detenerlos."; ["SUMMARY"] = "Defeat 80 trolls in Sarnúr"; };
[1879094069] = {["ID"] = 1879094069; ["i"] = 5; ["j"] = 2; ["k"] = 261; ["TYPE"] = 105; ["REP"] = 500; ["FACTION"] = 1879091340; ["NAME"] = "Los imprudentes"; ["LORE"] = "¡Has comido el queso!"; ["SUMMARY"] = "Eat Barrow-brie"; ["TITLE"] = "El Imprudente"; };
[1879099039] = {["ID"] = 1879099039; ["i"] = 6; ["j"] = 8; ["k"] = 3; ["TYPE"] = 103; ["VXP"] = 2000; ["LP"] = 5; ["REP"] = 500; ["FACTION"] = 1879091346; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Las Alturas Aterradoras"; ["LORE"] = "Aunque la mayoría de la gente sensata se queda en casa cuidando campos y talleres, algunos aventureros resistentes se sienten atraídos por los lugares más inhóspitos y difíciles de la Tierra Media. Pocos lugares presentan un desafío tan grande como el tramo de las Montañas Nubladas que rodea la región del Paso Alto, plagado de peligros —naturales y de otro tipo— capaces de poner a prueba hasta al más duro de los viajeros."; ["SUMMARY"] = "Find 8 mountain peaks in the Misty Mountains"; };
[1879099040] = {["ID"] = 1879099040; ["i"] = 6; ["j"] = 8; ["k"] = 4; ["TYPE"] = 103; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 500; ["FACTION"] = 1879091346; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Ciudad de los Trasgos"; ["LORE"] = "Pocos conocen toda la extensión de las profundidades de la Ciudad de los Trasgos, y quienes las han recorrido probablemente murieron allí como esclavos de crueles capataces trasgos. Los propios trasgos quizá no conozcan todos los caminos, pues los pasajes más profundos se adentran en el corazón de las Montañas Nubladas donde yacen terrores invisibles y oscuros, y los trasgos no se aventuran allí salvo que estén obligados o enloquecidos."; ["SUMMARY"] = "Find 7 areas in Goblin Town"; };
[1879099041] = {["ID"] = 1879099041; ["i"] = 6; ["j"] = 7; ["k"] = 5; ["TYPE"] = 103; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 500; ["FACTION"] = 1879091346; ["TIER"] = 2; ["MIN_LVL"] = 30; ["NAME"] = "Las Tierras Salvajes de Tâl Bruinen"; ["LORE"] = "El sur del Bosque de los Trolls está dominado por las Tierras Salvajes de Tâl Bruinen. Son pocos los que viven aquí ahora, incluso entre los Elfos, y las colinas boscosas se han vuelto densas y cubiertas de maleza, habitadas en su mayoría por bestias salvajes que representan un peligro constante para los viajeros y los pocos que intentan subsistir en estas tierras indómitas."; ["SUMMARY"] = "Find 5 locations in the wilderness of the Trollshaws"; };
[1879099095] = {["ID"] = 1879099095; ["i"] = 6; ["j"] = 8; ["k"] = 8; ["TYPE"] = 104; ["VXP"] = 2000; ["LP"] = 10; ["REP"] = 500; ["FACTION"] = 1879091346; ["TIER"] = 2; ["NAME"] = "Los Botones de Bilbo"; ["LORE"] = "Qué extraño... por los túneles de la Ciudad de los Trasgos parece haber un conjunto de viejos botones de latón desgastados, como si se hubieran perdido del chaleco de un hobbit. ¿Cómo habrán acabado estas cosas en estos oscuros y retorcidos pasadizos?"; ["SUMMARY"] = "Find Bilbo's 8 missing buttons"; };
