[1879107438] = {["ID"] = 1879107438; ["i"] = 5; ["j"] = 2; ["k"] = 253; ["TYPE"] = 105; ["REP"] = 1200; ["FACTION"] = 1879103953; ["NAME"] = "Desafío de la Liga de las Posadas"; ["LORE"] = "Para convertirse en un miembro respetado de la Liga de Tabernas, debe probar todas las cervezas, ales y vinos locales que se encuentran en todo Eriador. Busque todas estas bebidas para ganar el respeto de la Liga."; ["TITLE"] = "Sabio de Licores Finos de la Liga de las Posadas"; };
