[1879457857] = {["ID"] = 1879457857; ["i"] = 2; ["j"] = 15; ["k"] = 9; ["TYPE"] = 106; ["VXP"] = 2000; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Sant Lhoer, the Poison Gardens -- Tier 3"; ["LORE"] = "Sant Lhoer, conocido como los Jardines Emponzoñados de Carn Dûm, es un lugar húmedo repleto de plantas, árboles y flores mortales, como pocas o ninguna se han visto antes en la Tierra Media. Más allá de las aguas fétidas de color verde berilo que fluyen por Sant Lhoer, se alzan inmensas estructuras de cristal, incluyendo Bâr Heledh, la Casa de Cristal. Es aquí donde la hechicera Oganuin practica su arte, experimentando con criaturas, plantas y personas por igual. ¿Con qué fin y para qué propósito? Solo se pueden suponer los más oscuros designios."; ["TITLE"] = "Sembrador de aflicción de Sant Lhoer"; };
[1879457858] = {["ID"] = 1879457858; ["i"] = 2; ["j"] = 15; ["k"] = 6; ["TYPE"] = 105; ["VXP"] = 3000; ["TIER"] = 1; ["MIN_LVL"] = 140; ["NAME"] = "Deeds of Sant Lhoer, the Poison Gardens"; ["LORE"] = "Sant Lhoer, conocido como los Jardines Emponzoñados de Carn Dûm, es un lugar húmedo repleto de plantas, árboles y flores mortales, como pocas o ninguna se han visto antes en la Tierra Media. Más allá de las aguas fétidas de color verde berilo que fluyen por Sant Lhoer, se alzan inmensas estructuras de cristal, incluyendo Bâr Heledh, la Casa de Cristal. Es aquí donde la hechicera Oganuin practica su arte, experimentando con criaturas, plantas y personas por igual. ¿Con qué fin y para qué propósito? Solo se pueden suponer los más oscuros designios."; ["TITLE"] = "Senescal de Sant Lhoer"; };
[1879457859] = {["ID"] = 1879457859; ["i"] = 2; ["j"] = 15; ["k"] = 47; ["TYPE"] = 106; ["NA"] = 3; ["MIN_LVL"] = 140; ["NAME"] = "Sant Lhoer, the Poison Gardens -- Tier 3 -- Leading the Charge"; ["LORE"] = "Sant Lhoer, conocido como los Jardines Emponzoñados de Carn Dûm, es un lugar húmedo repleto de plantas, árboles y flores mortales, como pocas o ninguna se han visto antes en la Tierra Media. Más allá de las aguas fétidas de color verde berilo que fluyen por Sant Lhoer, se alzan inmensas estructuras de cristal, incluyendo Bâr Heledh, la Casa de Cristal. Es aquí donde la hechicera Oganuin practica su arte, experimentando con criaturas, plantas y personas por igual. ¿Con qué fin y para qué propósito? Solo se pueden suponer los más oscuros designios."; ["TITLE"] = "Lideró la carga en Sant Lhoer"; };
