[1879457861] = {["ID"] = 1879457861; ["i"] = 2; ["j"] = 15; ["k"] = 8; ["TYPE"] = 106; ["VXP"] = 2000; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Sant Lhoer, the Poison Gardens -- Tier 2"; ["LORE"] = "Sant Lhoer, conocido como los Jardines Emponzoñados de Carn Dûm, es un lugar húmedo repleto de plantas, árboles y flores mortales, como pocas o ninguna se han visto antes en la Tierra Media. Más allá de las aguas fétidas de color verde berilo que fluyen por Sant Lhoer, se alzan inmensas estructuras de cristal, incluyendo Bâr Heledh, la Casa de Cristal. Es aquí donde la hechicera Oganuin practica su arte, experimentando con criaturas, plantas y personas por igual. ¿Con qué fin y para qué propósito? Solo se pueden suponer los más oscuros designios."; ["TITLE"] = "Segador de Sant Lhoer"; };
[1879457863] = {["ID"] = 1879457863; ["i"] = 2; ["j"] = 15; ["k"] = 10; ["TYPE"] = 106; ["VXP"] = 1000; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Slayer of Sant Lhoer"; ["LORE"] = "Within Sant Lhoer, the Poison Gardens of Carn Dûm, are creatures and plants like none other in Middle-earth. Twisted by waters turned foetid by the terrible Helchgam, and further corrupted by dark sorceries, these unholy creations threaten to spill forth from the boundaries of Angmar."; ["TITLE"] = "Cosechador de Sant Lhoer"; };
