[1879458701] = {["ID"] = 1879458701; ["i"] = 2; ["j"] = 15; ["k"] = 48; ["TYPE"] = 106; ["NA"] = 3; ["MIN_LVL"] = 140; ["NAME"] = "Thaurisgar, the Vile Apothecary -- Tier 3 -- Leading the Charge"; ["LORE"] = "In the depths of Thaurisgar, countless foul and twisted experiments roam the shadows--the terrible legacy of Aniochán the Harrower. Before the fall of Carn Dûm, Aniochán worked tirelessly to outdo his rivals and win the favour of the Steward of Angmar. Chief among his tools in shaping his fell creations was a curious ichor known only as the Bile of Ifrinn. Thought to be lost after a disastrous experiment claimed Aniochán's life, now this foetid and vile substance is in danger of being let loose into the world."; ["TITLE"] = "Lideró la carga en Thaurisgar"; };
