[1879458871] = {["ID"] = 1879458871; ["i"] = 2; ["j"] = 15; ["k"] = 1; ["TYPE"] = 104; ["MIN_LVL"] = 135; ["NAME"] = "Uneasy Lies The Crown"; ["LORE"] = "Although the Angmarim of the Iron Crown and their allies among the Trév Duvárdain were scattered from Carn Dûm after the fall of the False King, Crannog, chieftain of the Trév Gállorg, has sent you a letter requesting your aid at Bail Avarc, hinting that all may not be well in Angmar."; };
