[1879459078] = {["ID"] = 1879459078; ["i"] = 2; ["j"] = 15; ["k"] = 18; ["TYPE"] = 104; ["VXP"] = 1000; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Alchemy of Thaurisgar"; ["LORE"] = "In the depths of Thaurisgar are remnants of Aniochán the Harrower's foul and twisted experiments. Key among the many tools used to shape his creations was the Bile of Ifrinn, a foetid ichor made by mixing the deadliest of ingredients and substances. Each ingredient carrying with it harmful and undesirable effects. It was in these vile and noxious substances that Aniochán the Harrower found the results he aspired to achieve."; ["TITLE"] = "el Ayudante del Alquimista"; };
[1879459101] = {["ID"] = 1879459101; ["i"] = 2; ["j"] = 15; ["k"] = 4; ["TYPE"] = 105; ["VXP"] = 3000; ["MIN_LVL"] = 140; ["NAME"] = "Deeds of Carn Dûm Resurgent"; ["LORE"] = "After the second downfall of Angmar, the Witch-king of Angmar's realm of old was left all but abandoned. Alas, the remnants of the Iron Crown have crept forth from the shadows and returned to the fortress-city of Carn Dûm, seeking to wield a lost artifact of the Witch-king of Angmar to seize dominion over the Free Peoples of Middle-earth."; ["TITLE"] = "Senescal de Angmar"; };
