[1879468428] = {["ID"] = 1879468428; ["i"] = 8; ["j"] = 10; ["k"] = 1; ["TYPE"] = 105; ["VXP"] = 4000; ["MIN_LVL"] = 133; ["NAME"] = "Deeds of Outer Gondor"; ["LORE"] = "In the aftermath of the War of the Ring, the peoples of Anfalas and Pinnath Gelin mourn the loss of their Lords while struggling against the Corsairs of Umbar and other foes to restore a long-absent peace in Outer Gondor."; ["TITLE"] = "Renovador de Gondor Exterior"; };
[1879468651] = {["ID"] = 1879468651; ["i"] = 5; ["j"] = 2; ["k"] = 55; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 5; ["TIER"] = 1; ["MIN_LVL"] = 13; ["NAME"] = "Enemigo / Enemiga de los lobos"; ["LORE"] = "Los lobos han sido durante mucho tiempo una plaga para los pacíficos Hobbits Ribereños del Valle de la Niebla. En los duros inviernos, a menudo merodean por los Manantiales del Langflood y los Valles de Anduin al sur, atacando al ganado y a los propios Hobbits Ribereños en manadas feroces. Sin embargo, hoy en día, uno debe preguntarse, ya que se han alejado del Norte en manadas cada vez más grandes, y parecen más que hambrientos: hay rumores de que muchas de estas manadas fueron criadas por algún nuevo mal para ser particularmente feroces, para atacar a los desprevenidos y a los débiles, y para olfatear a aquellos que pretenden esconderse de los ojos del Enemigo."; };
[1879468653] = {["ID"] = 1879468653; ["i"] = 5; ["j"] = 2; ["k"] = 54; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 10; ["MIN_LVL"] = 19; ["NAME"] = "Enemigo / Enemiga de los lobos II"; ["LORE"] = "Las leyendas hablan de trasgos, de murciélagos y de huargos leales a un antiguo señor orco que gobernaba el monte Gundabad. Se dice que su maldad era tan grande que atraía todo tipo de criaturas inmundas a las tierras circundantes, entre las cuales no se encuentran los feroces lobos que han molestado durante mucho tiempo a los Hobbits Ribereños del Valle de la Niebla. ¿Ha vuelto a suceder algo así? ¿Se agitan nuevos males en el Norte? Sea cual sea la verdad, parece un mal presagio que ahora se puedan encontrar lobos en casi toda la Tierra Media."; };
[1879468656] = {["ID"] = 1879468656; ["i"] = 5; ["j"] = 2; ["k"] = 57; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 5; ["TIER"] = 1; ["MIN_LVL"] = 19; ["NAME"] = "Enemigo / Enemiga de los trolls silvanos"; ["LORE"] = "Hace mucho tiempo, los Hobbits Ribereños del Valle de la Niebla se encontraron por primera vez con los demonios del Bosque Negro y los relatos de estas terribles criaturas pasaron a la leyenda. Entre los Elfos, se les llama trolls silvanos, y se dice que sus miembros nudosos gotean un veneno mortal, tan terrible que puede pudrir un bosque desde dentro."; };
[1879468657] = {["ID"] = 1879468657; ["i"] = 5; ["j"] = 2; ["k"] = 56; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 10; ["MIN_LVL"] = 25; ["NAME"] = "Enemigo / Enemiga de los trolls silvanos II"; ["LORE"] = "Existen muchas historias sobre los demonios del bosque del Norte, que se extendieron como una enfermedad pútrida a través del Viejo Bosque Verde. Los rumores dicen que otros seres similares han aparecido en tierras mucho más allá de los límites deL Bosque Negro y los Manantiales del Langflood, y muchos de los Hobbits Ribereños del Valle de la Niebla ahora creen que la propia naturaleza está siendo corrompida por alguna mano invisible."; };
[1879468717] = {["ID"] = 1879468717; ["i"] = 5; ["j"] = 2; ["k"] = 58; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 15; ["MIN_LVL"] = 30; ["NAME"] = "Enemigo / Enemiga de los Orcos y trasgos III"; ["LORE"] = "Los Orcos detestan casi tanto al sol como a sus inferiores, los trasgos, pero tienen más tolerancia hacia él y pueden ser forzados a soportarlo durante un tiempo cuando la necesidad o el látigo de sus amos lo exigen. A pesar de esto, los Hobbits Ribereños del Valle de la Niebla saben muy bien que los Orcos y trasgos del Norte a menudo merodean por las nieblas que se ciernen sobre los Manantiales del Langflood."; };
[1879468718] = {["ID"] = 1879468718; ["i"] = 5; ["j"] = 2; ["k"] = 59; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 10; ["TIER"] = 1; ["MIN_LVL"] = 25; ["NAME"] = "Enemigo / Enemiga de los Orcos y trasgos II"; ["LORE"] = "Los Orcos y los trasgos no son ni cobardes ni débiles, pero su fuerza y determinación a menudo desenfocadas son de poca utilidad contra un enemigo que no pueden encontrar, o un enemigo cuya existencia ni siquiera pueden estar seguros de que sea real. Las leyendas e historias persisten entre ellos sobre los Hobbits Ribereños del Valle de la Niebla, pero hay poco tiempo para hablar de tales trivialidades al servicio del Enemigo."; };
[1879468719] = {["ID"] = 1879468719; ["i"] = 5; ["j"] = 2; ["k"] = 60; ["TYPE"] = 106; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 19; ["NAME"] = "Enemigo / Enemiga de los Orcos y trasgos"; ["LORE"] = "Criados por el Enemigo para la guerra, los Orcos son más grandes y resistentes que sus primos trasgos, pero sus orígenes siguen siendo los mismos, y para los Hobbits Ribereños del Valle de la Niebla, hay poca distinción entre ellos. Belicosos y brutales, los Orcos y trasgos conservan cierto talento innato para el trabajo inteligente de la madera y el metal, aunque solo lo aplican a la construcción de armas y otras máquinas de guerra."; };
[1879468766] = {["ID"] = 1879468766; ["i"] = 5; ["j"] = 2; ["k"] = 61; ["TYPE"] = 105; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 5; ["MIN_LVL"] = 25; ["NAME"] = "Amigo / Amiga de los Olvidados"; ["LORE"] = "Te has convertido en un amigo de los Eglain, hombres que han rechazado la sociedad aceptada, eligiendo la vida escasa que las Tierras Solitarias pueden sostener. Aunque habitan en tierras menos hospitalarias que los Manantiales del Langflood, su forma de vida y su amistad con Radagast el Pardo te han llevado a considerarlos espíritus afines de los Hobbits Ribereños del Valle de la Niebla."; ["TITLE"] = "Corredor de Arroyos"; };
[1879468771] = {["ID"] = 1879468771; ["i"] = 5; ["j"] = 2; ["k"] = 62; ["TYPE"] = 104; ["CRV"] = "Race"; ["SUBTYPE"] = 125; ["LP"] = 10; ["MIN_LVL"] = 125; ["NAME"] = "De vuelta a la tierra conocida"; ["LORE"] = "Pocos entre los Hobbits Ribereños han viajado tan lejos de casa como tú, pero incluso después de todas tus aventuras, hay pocas cosas que te brindarían más consuelo que regresar al Valle de la Niebla."; ["TITLE"] = "Jinete de Corrientes"; };
