[1879477448] = {["ID"] = 1879477448; ["i"] = 10; ["j"] = 3; ["k"] = 1; ["TYPE"] = 105; ["VXP"] = 4000; ["MIN_LVL"] = 140; ["NAME"] = "Deeds of Umbar Baharbêl"; ["LORE"] = "In the aftermath of the Sea-stone Mutiny, Umbar Baharbêl has been freed from the Heirs of Castamir and their rulers in the Empire of Ordâkh. Under the governance of the Kindred of the Coins, a council of seven chosen by the citizens of Umbar Baharbêl, the City of the Corsairs struggles to be reborn as a Free City—with tidings of hope and treachery found in equal measure as its people step out from the darkness that was cast upon them long ago by the Dark Lord, Sauron."; ["TITLE"] = "de Umbar Baharbêl"; };
[1879477537] = {["ID"] = 1879477537; ["i"] = 10; ["j"] = 3; ["k"] = 3; ["TYPE"] = 105; ["VXP"] = 2000; ["LP"] = 5; ["TIER"] = 2; ["MIN_LVL"] = 140; ["NAME"] = "Tales of the Free City (Final)"; ["LORE"] = "Although they endured many years of oppression under the rule of Balakhôr the Scourge, the Heirs of Castamir, and the Empire of Ordâkh, the citizens of Umbar Baharbêl and the Kindred of the Coins who now lead them have remained steadfast in their efforts to preserve the Free City in the aftermath of the Sea-stone Mutiny."; };
