[1879482825] = {["ID"] = 1879482825; ["i"] = 10; ["j"] = 2; ["k"] = 23; ["TYPE"] = 104; ["VXP"] = 500; ["MIN_LVL"] = 150; ["NAME"] = "The Depths of Mâkhda Khorbo -- Azagath's Escape"; ["LORE"] = "The Mâkhda Khorbo, Temple of the All-Seeing, crumbled into ruin at the moment of Sauron's defeat, but remains a place of great interest for those seeking artifacts of evil. When Azagath Sea-shadow fled from the Citadel of Winds in the company of his comrades Belondor and Nakási Wave-reaper, his purpose was not escape alone. What treasure of the Dark Lord's might he have wrested from those buried ruins? Its identity remains unknown, but your pursuit of Azagath played a role in fracturing the bonds between some of these Kindred."; ["SUMMARY"] = "Stop Azagath Sea-shadow, Nakási Wave-reaper, and Belondor in the Mâkhda Khorbo"; };
