[1879486571] = {["ID"] = 1879486571; ["i"] = 10; ["j"] = 3; ["k"] = 76; ["TYPE"] = 103; ["VXP"] = 2000; ["MIN_LVL"] = 140; ["NAME"] = "Treasure-seeker of the Umbar-môkh"; ["LORE"] = "Find the many treasures hidden or forgotten throughout the Umbar-môkh."; ["TITLE"] = "Buscador de tesoros del Umbar-môkh"; };
[1879487903] = {["ID"] = 1879487903; ["i"] = 5; ["j"] = 4; ["k"] = 458; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Derrota al Sureño Sombrío"; ["LORE"] = "Pocos entre los vivos lo escucharon hablar, pero su rostro era bien conocido y temido. Lo llamaban el Sureño Sombrío, y mientras los Hombres temblaban ante su presencia durante la Segunda Edad, durante la Tercera la leyenda de su malicia solo había crecido. En días posteriores, fue él a quien Lhaereth la Manchada siguió en secreto a Dol Guldur, donde descubrió a Sauron y lo ayudó a recuperarse, por un precio. ¿El Señor Oscuro recompensó o castigó la falta de su Nazgûl? Pero eso fue mucho más tarde. Durante la Segunda Edad, el Sureño Sombrío era conocido solo por ser paciente, leal y silencioso."; ["TITLE"] = "Amanecer del Sur"; };
[1879487969] = {["ID"] = 1879487969; ["i"] = 5; ["j"] = 4; ["k"] = 466; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Derrota al Rey Brujo"; ["LORE"] = "El más grande y temido de los Nueve, el Rey Brujo acechaba el campo de batalla pero rara vez, dejando las fortalezas de Mordor solo bajo la orden más urgente de Sauron. En años posteriores, el Señor de los Nazgûl levantaría de la nada la Tierra de Angmar, utilizándola para avanzar en el objetivo del Señor Oscuro de destruir el reino del norte de Arnor, pero al final de la Segunda Edad eso aún estaba lejos en las brumas del Tiempo. Durante el Asedio de Barad-dûr, el Rey Brujo se encontraba probando las debilidades de los ejércitos alineados contra su maestro, buscando el premio más valioso de todos: la información."; ["TITLE"] = "la Última Esperanza del Norte"; };
[1879487972] = {["ID"] = 1879487972; ["i"] = 5; ["j"] = 4; ["k"] = 465; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Derrota al Jinete Maldito"; ["LORE"] = "Se movía rápidamente por el campo de batalla, persiguiendo a los guerreros que se atrevían a enfrentarse a él, cada vez menos a medida que avanzaba el asedio. Era el Jinete Maldito, y el sonido de su acercamiento convertía incluso la sangre más valiente en agua. En años posteriores comandaría ejércitos desde dentro de los muros de Dol Guldur, pero durante la Segunda Edad prefería luchar desde el lomo de su corcel negro, solo."; ["TITLE"] = "Rompemaldiciones"; };
[1879487973] = {["ID"] = 1879487973; ["i"] = 5; ["j"] = 4; ["k"] = 464; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Derrota a la Amargura de Khand"; ["LORE"] = "Era la Amargura de Khand y, con la bendición de Sauron, avanzó por las tierras no conquistadas y las reclamó para el Señor Oscuro. El anillo que se le otorgó se llamaba Adâsh, y muchos fueron los enemigos que creó, muchos los orgullosos guerreros que abatió. Encontraba gran alegría en provocar la guerra, y siempre lo había hecho, pero con el poder otorgado por Sauron, la Amargura de Khand se volvió cada vez más mortal, más implacable y más despiadada."; ["TITLE"] = "la Alegría de Khand"; };
[1879487974] = {["ID"] = 1879487974; ["i"] = 5; ["j"] = 4; ["k"] = 463; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Derrota al Sumo Hechicero de Harad"; ["LORE"] = "Lo llamaban el Sumo Hechicero de Harad, pero para la mayoría de los que luchaban contra Sauron era solo un nombre. Rara vez salía de los calabozos de Mordor, ya que se deleitaba en la realización de rituales abominables y en el dominio de la magia oscura, y dedicaba su pensamiento a poco más. Pero cuando el Señor Oscuro consideraba oportuno enviarlo, Hombres y Elfos sabían que debían darle un amplio margen, o sufrir. Era Mêbat quien llevaba, el Devorador de Alegría, y dondequiera que iba, había un fin a la risa, y solo el inicio del dolor."; ["TITLE"] = "la Caída del Hechicero"; };
[1879487975] = {["ID"] = 1879487975; ["i"] = 5; ["j"] = 4; ["k"] = 462; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Derrota al Daño de Rhûn"; ["LORE"] = "Una vez fue un gran rey en tierras lejanas al este, acostumbrado a gobernar y reacio a inclinar la rodilla ante cualquier otro. Pero luego vino un dador de regalos y un prometedor de poder, y al aceptar estos señuelos, el gran rey cambió. Ya no gobernaba sus tierras con misericordia, y tampoco permanecía en su propio reino. Se convirtió en el Daño de Rhûn, y con ese nombre llegó a ser conocido como el Daño de Rhûn, y en otros lugares."; ["TITLE"] = "Salvador de Rhûn"; };
[1879487976] = {["ID"] = 1879487976; ["i"] = 5; ["j"] = 4; ["k"] = 461; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Derrota a la Espada Negra de Lebennin"; ["LORE"] = "En días posteriores, la Espada Negra de Lebennin fue vista con frecuencia merodeando entre las colinas y los bosques de Gondor Occidental, infundiendo miedo en los corazones de los Hombres con su temible presencia y su espada mortal. Para aquellos pocos que no huían, sus palabras caían como miel en sus oídos reacios y los llevaban a cometer terribles actos de maldad. Esto pudo haber demostrado ser su peor y más eficaz arma."; ["TITLE"] = "el Quebrantahojas"; };
[1879487977] = {["ID"] = 1879487977; ["i"] = 5; ["j"] = 4; ["k"] = 460; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Derrota a la Languidez de Nurn"; ["LORE"] = "Nadie puede decir qué barco lo llevó a la Tierra Media antes de que Númenor se perdiera, pero una vez que aceptó el regalo de Sauron, ya no podía ser contado entre los Hombres de esa tierra. Habitó en Thaurband, una fortaleza en el sur de Mordor, no lejos del Mar Interior. Desde esa fortaleza se extendió el miedo hacia él, dándole un nuevo título para reemplazar el nombre que ya no necesitaba. Se convirtió en la Languidez de Núrn, aunque no permaneció allí, y vagó por todas partes bajo el mando de Sauron."; ["TITLE"] = "una Luz en la Penumbra"; };
[1879487978] = {["ID"] = 1879487978; ["i"] = 5; ["j"] = 4; ["k"] = 459; ["TYPE"] = 102; ["VEIL_OF_THE_NINE"] = true; ["TIER"] = 1; ["MIN_LVL"] = 45; ["NAME"] = "Derrota al Despojador Proscrito"; ["LORE"] = "Desde el lejano sur llegó, trayendo miedo y fuego a cada costa que espiaba con su cristal. Su reinado era de sangre, y la extraía de todos los que vivían a la vista y al olor del Mar. ¿Fue esa la razón por la que Sauron le dio el anillo Khânto, que es el Dador de Dolor? Con el poder de él, el Despojador Proscrito no podía ser detenido, y su risa se extendía tierra adentro con vientos funestos; estaba entre los sirvientes más rápidos y crueles de Sauron."; ["TITLE"] = "No Más Abandonado"; };
[1879489234] = {["ID"] = 1879489234; ["i"] = 5; ["j"] = 4; ["k"] = 441; ["TYPE"] = 105; ["TIER"] = 2; ["NAME"] = "Chismoso / Chismosa"; ["LORE"] = "Fuiste derribado por un hobbit ladrón en el Evento Galletas Duras de la Mansión de Thorin varias veces."; ["TITLE"] = "Soplón"; };
[1879489238] = {["ID"] = 1879489238; ["i"] = 5; ["j"] = 4; ["k"] = 440; ["TYPE"] = 105; ["TIER"] = 1; ["NAME"] = "Torpe"; ["LORE"] = "Muchos hobbits descarados han sido bien alimentados por tu torpeza inepta. Por este ignoble honor, serás conocido como un torpe para siempre."; ["TITLE"] = "el Terrón"; };
