[1879489251] = {["ID"] = 1879489251; ["i"] = 5; ["j"] = 4; ["k"] = 444; ["TYPE"] = 105; ["TIER"] = 2; ["NAME"] = "Fallo al Encender la Forja"; ["LORE"] = "Sea cual sea la razón, permitiste que estos mineros perezosos de Ukhbab-gairu te hicieran perder mineral más veces de las que a un enano le importa contar. Tus fracasos provocaron que los fuegos de la forja fallaran."; ["TITLE"] = "Falló al Disparar"; };
