[1879494779] = {["ID"] = 1879494779; ["i"] = 2; ["j"] = 17; ["k"] = 12; ["TYPE"] = 106; ["VXP"] = 1500; ["TIER"] = 2; ["MIN_LVL"] = 150; ["NAME"] = "Nirgambâr, the Restless Tomb-- Tier 3"; ["LORE"] = "In a sheltered valley in the north of Khûd Zagin stand ancient, crumbling ziggurat-tombs of pale stone collectively known as Nirgambâr. Scouts have reported that one of the Zidemel's men, Andur, is said to have entered Nirgambâr drawn their by dark whispers. Locate and stop Andur before he can unleash what lurks in this cursed place."; };
