[1879496461] = {["ID"] = 1879496461; ["i"] = 2; ["j"] = 17; ["k"] = 3; ["TYPE"] = 106; ["VXP"] = 1000; ["TIER"] = 1; ["MIN_LVL"] = 150; ["NAME"] = "Nâkhugir's Bane"; ["LORE"] = "We have discovered a dangerous cult of usan-kûni worshippers hiding in our own back-yard. They call themselves Anâkhi, and have made their home inside Ashunûg, a salt mine in northern Ambarûl that has long been abandoned. We are only recently freed of Sauron, the All-seeing, and must not allow this new cult to take hold. The Anâkhi scorpion worshippers must be driven from our lands."; ["TITLE"] = "El daño de Nâkhugir"; };
[1879496462] = {["ID"] = 1879496462; ["i"] = 2; ["j"] = 17; ["k"] = 39; ["TYPE"] = 106; ["NA"] = 3; ["MIN_LVL"] = 150; ["NAME"] = "Ashunûg, the Fane of the Accursed -- Tier 3 -- Leading the Charge"; ["LORE"] = "We have discovered a dangerous cult of usan-kûni worshippers hiding in our own back-yard. They call themselves Anâkhi, and have made their home inside Ashunûg, a salt mine in northern Ambarûl that has long been abandoned. We are only recently freed of Sauron, the All-seeing, and must not allow this new cult to take hold. The Anâkhi scorpion worshippers must be driven from our lands."; ["TITLE"] = "Lideró la Carga en Ashunûg"; };
