[1879500027] = {["ID"] = 1879500027; ["i"] = 2; ["j"] = 17; ["k"] = 42; ["TYPE"] = 106; ["NA"] = 3; ["MIN_LVL"] = 145; ["NAME"] = "Temple of Utug-bûr -- Leading the Charge"; ["LORE"] = "Utug-bûr is home long-hidden vaults delved deep into the stone, hidden by sorcery since the end of the First Age. The Thardúth, one of Morgoth's powerful agents, bred the great Elder Orcs known as the Utûgi. Its denizens have remained in a sorcerous slumber for millennia, but have now awakened, and their lair opened anew with the passing of the threat of Sauron."; ["TITLE"] = "Lideró la Carga en el Templo de Utug-bûr"; };
