[1879519553] = {["ID"] = 1879519553; ["i"] = 2; ["j"] = 18; ["k"] = 1; ["TYPE"] = 106; ["VXP"] = 3000; ["LP"] = 10; ["REP"] = 700; ["FACTION"] = 1879506206; ["MIN_LVL"] = 150; ["NAME"] = "Conflicts of Mûr Ghala"; ["LORE"] = "You have proven yourself by defeating Bârlat and his brigands inside the Treasure Caves of Hurum Kâna; pushing back the darkness within Kôth Rau, the Wailing Hold; investigating the disturbances inside Ekal-nêbi, the Fallen Palace; and surviving what lay inside the Folly of Nagakhêdi. None can question your tenacity and determination, and by completing all these deeds, you have earned great favour throughout Mûr Ghala."; ["TITLE"] = "Presagio de Luz"; };
